#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int cmp_char(const void *a, const void *b) {
    return (*(char*)a - *(char*)b);
}

int cmp_str(const void *a, const void *b) {
    return strcmp((char*)a, (char*)b);
}

char keys[10005][105];

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) {
        scanf("%s", keys[i]);
        int len = strlen(keys[i]);
        qsort(keys[i], len, sizeof(char), cmp_char);
    }
    qsort(keys, n, sizeof(keys[0]), cmp_str);
    int groupCount = n > 0 ? 1 : 0;
    for (int i = 1; i < n; i++) {
        if (strcmp(keys[i], keys[i-1]) != 0) {
            groupCount++;
        }
    }
    printf("%d\n", groupCount);
    return 0;
}
